/// <summary>
/// Extension of class <c>SalesInvoiceDP</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDP))]
final class KPMGSalesInvoiceDP_Extension
{   

}

Method.Source:
    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_companyInfo">_companyInfo</param>
    protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour,
                                                        CompanyInfo _companyInfo)
    {
        next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);   
        
        SalesTable                  salesTable;
        MarkupTrans                 markupTrans;
        

        salesTable = SalesTable::find(salesInvoiceHeaderFooterTmp.SalesId);
        salesInvoiceHeaderFooterTmp.KPMGDeliveryName        = salesTable.DeliveryName;
        salesInvoiceHeaderFooterTmp.KPMGDeliveryAddress     = salesTable.deliveryAddressing();
        salesInvoiceHeaderFooterTmp.KPMGDeliveryDate        = salesTable.DeliveryDate;
        salesInvoiceHeaderFooterTmp.KPMGOrderDiscount       = salesTable.DiscPercent;
        salesInvoiceHeaderFooterTmp.KPMGCashDiscDesc        = CashDisc::find(salesTable.CashDisc).Description;
        salesInvoiceHeaderFooterTmp.KPMGPurchOrderFormNum   = salesTable.PurchOrderFormNum;
        //MPJ_31513 Invoicing Design 
        Map metChargesMap = new Map(Types::String, Types::Real);
        //MPJ_31513 Invoicing Design 

        salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       = "";
        salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  = "";
        salesInvoiceHeaderFooterTmp.METDeliveryFee          =0;
        salesInvoiceHeaderFooterTmp.METAdminFee             =0;
        while select markupTrans
            where markupTrans.TransTableId   == _custInvoiceJour.TableId
            && markupTrans.TransRecId        == _custInvoiceJour.RecId
        {
            // Filter out ledger to Ledger.
            if (!(markupTrans.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTrans.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       += markupTrans.MarkupCode + '\n';
                salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  += strFmt('%1',markupTrans.CalculatedAmount) + '\n';
            } 
            if(metChargesMap.exists(markupTrans.Txt))
            {
                metChargesMap.insert(markupTrans.Txt, metChargesMap.lookup(markupTrans.MarkupCode)+markupTrans.CalculatedAmount);
            }
            else
            {      
                metChargesMap.insert(markupTrans.Txt, markupTrans.CalculatedAmount);
            }
            if(markupTrans.markupTable().METDlvCharge)
            {
                salesInvoiceHeaderFooterTmp.METDeliveryFee          += markupTrans.Value;
            }
            if(markupTrans.markupTable().METAdminCharge)
            {
                salesInvoiceHeaderFooterTmp.METAdminFee             += markupTrans.Value;
            }
        }

        //MPJ_31513 Invoicing Design Begin

        markupTrans metMarkupTransInvoiceStd;
        CustInvoiceTrans    metCustInvoiceTransInvoiceStd;
        CustInvoiceJour     metCustInvoiceJourStd;
        while select sum(CalculatedAmount) from metMarkupTransInvoiceStd
            group by txt 
           exists join metCustInvoiceTransInvoiceStd
            where metCustInvoiceTransInvoiceStd.TableId  == metMarkupTransInvoiceStd.TransTableId &&
                  metCustInvoiceTransInvoiceStd.RecId     == metMarkupTransInvoiceStd.TransRecId  &&
                  metCustInvoiceTransInvoiceStd.InvoiceId      == _custInvoiceJour.InvoiceId 
          
        {
            if(metChargesMap.exists(metMarkupTransInvoiceStd.Txt))
            {
                metChargesMap.insert(metMarkupTransInvoiceStd.Txt, metChargesMap.lookup(metMarkupTransInvoiceStd.MarkupCode)+metMarkupTransInvoiceStd.CalculatedAmount);
            }
            else
            {
                metChargesMap.insert(metMarkupTransInvoiceStd.Txt, metMarkupTransInvoiceStd.CalculatedAmount);
            }            
            
        }

        MapEnumerator       metMapEnumeratorStd;
        metMapEnumeratorStd = metChargesMap.getEnumerator();
        while (metMapEnumeratorStd.moveNext())
        {
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesCode       += metMapEnumeratorStd.currentKey() + '\n';
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesValue  += strFmt('%1',metMapEnumeratorStd.currentValue()) + '\n';
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesTotal +=metMapEnumeratorStd.currentValue();
            
        }

        CustFormLetterParameters custFormLetterParameters = CustFormLetterParameters::find();

        CustParameters      custParams          = CustParameters::find();
        CustTable           custTable           = _custInvoiceJour.custTable_OrderAccount();
        METCustTable        metCustTable        = METCustTable::find(custTable.AccountNum);
              
        CompanyInfo         companyInfo         = CompanyInfo::find();

        salesInvoiceHeaderFooterTmp.CompanyEmail = companyInfo.email();

        // MPJ-13531
        Image img = CustTable::metGetCustReportLogo(_custInvoiceJour.InvoiceAccount);
        
        if(img)
        {
            salesInvoiceHeaderFooterTmp.companyLogo = img.getData();
        }

        BankAccountTable    eftBankAccount = BankAccountTable::find(companyInfo.Bank);
        
        
        METIndustryKeyTable METIndustryKeyTable = METIndustryKeyTable::find(METCustTable::find(custInvoiceJour.InvoiceAccount).IndustryKey);
        salesInvoiceHeaderFooterTmp.CompanyCoRegNum = METIndustryKeyTable.CoRegNum;
        salesInvoiceHeaderFooterTmp.CompanyPhone    = METIndustryKeyTable.SOInvPhone;
        salesInvoiceHeaderFooterTmp.CompanyEmail    = METIndustryKeyTable.SOInvEmail;
        salesInvoiceHeaderFooterTmp.CompanyName     = METIndustryKeyTable.CompanyName;
         
        
        CustInvoiceTrans    metCustInvoiceTransStd;
        InventDim    metInventDimStd;
        select firstonly inventSiteId, InventLocationId from  metInventDimStd
        exists join metCustInvoiceTransStd
            where metCustInvoiceTransStd.inventDimId    == metInventDimStd.inventDimId &&
            metCustInvoiceTransStd.ParentRecId    == _custInvoiceJour.RecId;

        MarkupTable metMarkupTableStd = MarkupTrans::findValue(custInvoiceJour.TableId,custInvoiceJour.RecId).markupTable();

        salesInvoiceHeaderFooterTmp.METBranchNumber = metInventDimStd.InventLocationId;
        salesInvoiceHeaderFooterTmp.METBranchName   = InventLocation::find(metInventDimStd.InventLocationId).Name;

        LogisticsPostalAddress metLogisticsPostalAddressStd = LogisticsPostalAddress::findByLocation(InventLocation::getLocationFromRole(InventLocation::find(metInventDimStd.InventLocationId).RecId, LogisticsLocationRoleType::Delivery));

        // CB246_LicenseChecks
        // Revisit report later as the table name changed and customer licence tables merged
        /*LicenseTableMETMetcashTobaccoLiqLicenseTable    metMetcashTobaccoLiqLicenseTable;
        select firstonly TobaccoLicenceNumber, LiquorLicenceNumber from metMetcashTobaccoLiqLicenseTable
            where metMetcashTobaccoLiqLicenseTable.InventSiteId == metInventDimStd.InventSiteId &&
            metMetcashTobaccoLiqLicenseTable.StateId      == metLogisticsPostalAddressStd.State;
        
        METCustLiquorLicenseTable metCustLiquorLicenseTable;
        select firstonly LiquorLicenceNumber from metCustLiquorLicenseTable
            where metCustLiquorLicenseTable.CustomerNumber == _custInvoiceJour.InvoiceAccount &&
                  metCustLiquorLicenseTable.LiquorLicenceState == metLogisticsPostalAddressStd.State;
        */
        salesInvoiceHeaderFooterTmp.METSupplierSiteNameAddress  = metLogisticsPostalAddressStd.Address;

        salesInvoiceHeaderFooterTmp.METInvoiceReportInternetBankingNotes = custFormLetterParameters.METInvoiceReportInternetBankingNotes;
        salesInvoiceHeaderFooterTmp.METEFTAccountDetails    = strFmt('BSB: %1 A/C: %2', eftBankAccount.BankSortCode, eftBankAccount.AccountNum);
        salesInvoiceHeaderFooterTmp.METEFTReferenceText     = metCustTable.BsbReference;
        salesInvoiceHeaderFooterTmp.METStatementDate        = salesInvoiceHeaderFooterTmp.InvoiceDate;
        salesInvoiceHeaderFooterTmp.METBPayBillerCode       = metCustTable.BPayBillerCode;
        salesInvoiceHeaderFooterTmp.METBPayReference        = metCustTable.BPayReference;        
        salesInvoiceHeaderFooterTmp.METDeliveryRoute        = salesTable.METRoute+' / '+ int2Str(salesTable.METRouteStopNum);
        salesInvoiceHeaderFooterTmp.METCustGroup            = custTable.CustGroup;
        // CB246_LicenseChecks
        // Revisit report later as the table name changed and customer licence tables merged
        //salesInvoiceHeaderFooterTmp.METCustTobaccoLicense   = METCustTobaccoLicenseTable::find(custInvoiceJour.InvoiceAccount).TobaccoLicenceNumber;
        salesInvoiceHeaderFooterTmp.METPaymTerms            = salesTable.Payment;
        salesInvoiceHeaderFooterTmp.METDueDate              = _custInvoiceJour.DueDate;
        salesInvoiceHeaderFooterTmp.METSalesOrderType       = salesTable.METSalesOrderType;
        
        // CB246_LicenseChecks
        // Revisit report later as the table name changed and customer licence tables merged
        /*salesInvoiceHeaderFooterTmp.METCustLiquorLicense   = metCustLiquorLicenseTable.LiquorLicenceNumber;        
        salesInvoiceHeaderFooterTmp.METTobaccoLicense       = metMetcashTobaccoLiqLicenseTable.TobaccoLicenceNumber;
        salesInvoiceHeaderFooterTmp.METLiquorLicense        = metMetcashTobaccoLiqLicenseTable.LiquorLicenceNumber;*/
        salesInvoiceHeaderFooterTmp.METRepCode              = salesTable.SalesGroup;
        salesInvoiceHeaderFooterTmp.METBPayMessage          = custFormLetterParameters.METBpayMessageToCustomer;
        salesInvoiceHeaderFooterTmp.METDeliverToName        = salesTable.DeliveryName;
        salesInvoiceHeaderFooterTmp.METDeliverToAddress     = salesTable.deliveryAddress().Address;
        salesInvoiceHeaderFooterTmp.METInvoiceToABN         = custTable.VATNum;
        custTable                   metCustTableStd;
        DirPartyLocation            metDirPartyLocationStd;
        LogisticsElectronicAddress  metLogisticsElectronicAddressStd;     

        select  firstOnly Locator from metLogisticsElectronicAddressStd
            order by metLogisticsElectronicAddressStd.IsPrimary desc
            exists join metDirPartyLocationStd
            exists join metCustTableStd
            where metLogisticsElectronicAddressStd.Location == metDirPartyLocationStd.Location && 
                  metLogisticsElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Phone &&
                  metCustTableStd.Party == metDirPartyLocationStd.Party &&
                  metCustTableStd.AccountNum == salesTable.InvoiceAccount;

        salesInvoiceHeaderFooterTmp.METInvoiceToPhone       = metLogisticsElectronicAddressStd.Locator;
        salesInvoiceHeaderFooterTmp.METShipToPhone          = salesTable.deliveryPhone(); 
        salesInvoiceHeaderFooterTmp.METRemittanceEmail      = companyInfo.email();

        //MPJ_31513 Invoicing Design End




    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <param name = "_taxSpec">_taxSpec</param>
    /// <param name = "_custPaymSchedLine">_custPaymSchedLine</param>
    /// <param name = "_prepaymentCustTrans">_prepaymentCustTrans</param>
    /// <param name = "_prepaymentTaxTrans">_prepaymentTaxTrans</param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
                                            CustInvoiceTrans _custInvoiceTrans,
                                            TaxSpec _taxSpec,
                                            CustPaymSchedLine _custPaymSchedLine,
                                            CustTrans _prepaymentCustTrans,
                                            TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(_custInvoiceJour,
                                    _custInvoiceTrans,
                                    _taxSpec,
                                    _custPaymSchedLine,
                                    _prepaymentCustTrans,
                                    _prepaymentTaxTrans);
        
        //MPJ_31513 Invoicing Design Begin         
        

        QueryRun tradeLoopTrans = new tradeLoopTrans(_custInvoiceTrans, tableNum(markupTrans)).buildQueryRun();
        
        salesInvoiceTmp.MCRMarkupTxt = SysLabel::labelId2String(literalStr("@SYS308474"),  _custInvoiceJour.LanguageId);

        while (tradeLoopTrans.next())
        {
            MarkupTrans markupTransLocal = tradeLoopTrans.get(tableNum(markupTrans));

            // Filter out ledger to Ledger.
            if (!(markupTransLocal.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTransLocal.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceTmp.MCRMarkupTxt += '\n' + markupTransLocal.MarkupCode + " = " +strFmt('%1',markupTransLocal.CalculatedAmount) ;
               
            }
            
        }

        SalesLine salesLine = SalesLine::findInventTransId(_custInvoiceTrans.InventTransId);
        salesInvoiceTmp.METINDS                         = salesLine.metSalesLine().Indicators;
        salesInvoiceTmp.METSuppliedQty                  = _custInvoiceTrans.Qty;        
        salesInvoiceTmp.METWeight                       = METWHSPhysDimUOMSite::convertWeight(_custInvoiceTrans.ItemId, _custInvoiceTrans.Qty, _custInvoiceTrans.SalesUnit, _custInvoiceTrans.inventDim());
        TaxTrans    metTaxTransStd;
        select TaxValue from metTaxTransStd            
            where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId;
        salesInvoiceTmp.METTaxPercent                   = metTaxTransStd.TaxValue;
        
        select TaxCode, sum(SourceTaxAmountCur),sum(SourceTaxAmountCur) from metTaxTransStd
            group by TaxCode
            where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId;
        
        salesInvoiceTmp.METLineNum                      = _custInvoiceTrans.LineNum;
        MarkupTrans metMarkupTransStd                   = MarkupTrans::findValue(_custInvoiceTrans.TableId, _custInvoiceTrans.RecId);
        
        salesInvoiceTmp.MarkupCode                      = metMarkupTransStd.MarkupCode;
        salesInvoiceTmp.MarkupAmount                    = metMarkupTransStd.CalculatedAmount;
        salesInvoiceTmp.METCAT                          = MetItemSiteSettingsSetup::find(_custInvoiceTrans.ItemId,_custInvoiceTrans.inventSiteId()).ItemType;
        salesInvoiceTmp.METSalesInvoiceReportLineType   = METSalesInvoiceReportLineType::Line;
        salesInvoiceTmp.METAlcoholCategory              = METItemType::find(MetItemSiteSettingsSetup::find(_custInvoiceTrans.ItemId,_custInvoiceTrans.inventSiteId()).ItemType).Description;
        
        salesInvoiceTmp.METRetailAmount                 = salesInvoiceTmp.LineAmount;
        salesInvoiceTmp.METDeliveryFee                  = MarkupTrans::findValue(_custInvoiceTrans.TableId,_custInvoiceTrans.RecId).getCalculatedAmountRepresentable();
        
        if(metTaxTransStd.TaxCode == '0')
        {
            salesInvoiceTmp.METGST      = '';
        }
        else
        {
            salesInvoiceTmp.METGST      = 'Y';
        }
        select TaxCode, sum(SourceTaxAmountCur) from metTaxTransStd
            group by TaxCode
            where metTaxTransStd.InventTransId  == _custInvoiceTrans.InventTransId &&
                  metTaxTransStd.TaxCode        == 'WET';
        if(metTaxTransStd.TaxCode == 'WET')
        {
            salesInvoiceTmp.METWET      = 'Y';
            salesInvoiceTmp.METWETValue = abs(metTaxTransStd.SourceTaxAmountCur);
        }
        else
        {
            salesInvoiceTmp.METWET      = '';
        }
        salesInvoiceTmp.METWholesaleListPrice           = _custInvoiceTrans.SalesPrice;
        
             
        if(_custInvoiceTrans.SalesUnit == 'ea')
        {
            salesInvoiceTmp.METPackQty=1;
        }
        else
        {
        
            salesInvoiceTmp.METPackQty                    =  UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
        }

         if(_custInvoiceTrans.SalesUnit == 'ea')
         {
             salesInvoiceTmp.METAlcLitres                    = METInventTable::find(_custInvoiceTrans.ItemId).BottleSize * _custInvoiceTrans.Qty;
         }
         else
         {
             salesInvoiceTmp.METAlcLitres                    = METInventTable::find(_custInvoiceTrans.ItemId).BottleSize * salesInvoiceTmp.METPackQty;
         }

          
        salesInvoiceTmp.METSize                         = METInventTable::find(_custInvoiceTrans.ItemId).ItemSize;        
        
        salesInvoiceTmp.TaxAmount                       = _custInvoiceTrans.TaxAmount+metMarkupTransStd.TaxAmount;        
        salesInvoiceTmp.METRebatesFees                  = metMarkupTransStd.CalculatedAmount;
        salesInvoiceTmp.LineAmountInclTax               = _custInvoiceTrans.LineAmount+salesInvoiceTmp.TaxAmount+salesInvoiceTmp.METRebatesFees;
        if(!salesInvoiceTmp.TaxAmount && !metMarkupTransStd.TaxAmount)
        {
            salesInvoiceTmp.METAmountTaxExempt              = _custInvoiceTrans.LineAmount;
        }
        
        salesInvoiceTmp.METUnitPriceExclTax             = _custInvoiceTrans.SalesPrice;
        salesInvoiceTmp.METUnitPriceInclTax             = _custInvoiceTrans.Qty ? (_custInvoiceTrans.lineAmountInclTax() / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METOrderedQty                   = _custInvoiceTrans.salesLine().SalesQty;        
        salesInvoiceTmp.METUnitTax                      = _custInvoiceTrans.Qty ? (_custInvoiceTrans.TaxAmount / _custInvoiceTrans.Qty) : 0;
        salesInvoiceTmp.METProductType                  = METItemType::find(MetItemSiteSettingsSetup::find(_custInvoiceTrans.ItemId,_custInvoiceTrans.inventSiteId()).ItemType).Description;        
        salesInvoiceTmp.METSRP                          = salesInvoiceTmp.LineAmount;        
        METIndustryKeyTable METIndustryKeyTable = METIndustryKeyTable::find(METCustTable::find(_custInvoiceJour.InvoiceAccount).IndustryKey);
        salesInvoiceTmp.FormLetterRemarksTxt            = METIndustryKeyTable.SOInvFormNote;
        salesInvoiceTmp.METCase                         = EcoResProductUnitConverter::convertForReleasedProduct(
                                                    _custInvoiceTrans.ItemId,
                                                    _custInvoiceTrans.InventDimId,
                                                    _custInvoiceTrans.Qty,                                                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_custInvoiceTrans.SalesUnit),
                                                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(METConstants::unitcase),
                                                    NoYes::Yes,
                                                    NoYes::No);
        if(_custInvoiceTrans.METCase)
        {
            SalesInvoiceTmp.METCaseCost                     = salesInvoiceTmp.METWholesaleListPrice+(salesInvoiceTmp.METDeliveryFee+_custInvoiceTrans.lineAmountInclTax())/_custInvoiceTrans.METCase;
        }
        salesInvoiceTmp.METLucInclGST                   = (salesInvoiceTmp.LineAmountInclTax/_custInvoiceTrans.Qty)/salesInvoiceTmp.METPackQty;
        salesInvoiceTmp.Name                            = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber( _custInvoiceTrans.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
        salesInvoiceTmp.METGTIN                         = InventItemGTIN::find(_custInvoiceTrans.ItemId,_custInvoiceTrans.InventDimId,_custInvoiceTrans.SalesUnit).GlobalTradeItemNumber;
        Amount metLineAmountWithDeliveryWET             = (salesInvoiceTmp.SalesPrice*salesInvoiceTmp.Qty)+salesInvoiceTmp.METWETValue+salesInvoiceTmp.METDeliveryFee;
        salesInvoiceTmp.METLucExclGST                   = (metLineAmountWithDeliveryWET/salesInvoiceTmp.Qty)/salesInvoiceTmp.METPackQty;
        //MPJ_31513 Invoicing Design End

    }
